func (this *Hyperliquid) unWatchMyTradesBody(ch chan ccxt.AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbol *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	if symbol != nil {
		panic(ccxt.NotSupported(this.Id + " unWatchMyTrades does not support a symbol argument, unWatch from all markets only"))
	}
	var userAddress *string = nil
	var userAddressResult any = this.HandlePublicAddress("unWatchMyTrades", params)
	userAddress = this.SafeString(userAddressResult, 0)
	var paramsValue any = this.SafeDict(userAddressResult, 1, params)
	var messageHash string = "unsubscribe:myTrades"
	var url *string = ccxt.SafeStringPtr(ccxt.GetValue(ccxt.GetValue(this.Urls["api"], "ws"), "public"))
	var request map[string]any = map[string]any{
		"method": "unsubscribe",
		"subscription": map[string]any{
			"type": "userFills",
			"user": userAddress,
		},
	}
	var message map[string]any = this.Extend(request, paramsValue)

	r1 := <-this.Watch(url, messageHash, message, messageHash)
	if r1.Err != nil {
		panic(r1.Err)
	}
	ch <- ccxt.AsyncResult[any]{Value: r1.Value}
	return nil
}
func (this *Hyperliquid) HandleWsTickers(client any, message map[string]any) bool {
	// hip3 mids
	// {
	//     channel: 'allMids',
	//     data: {
	//         dex: 'flx',
	//         mids: {
	//         'flx:COIN': '270.075',
	//         'flx:CRCL': '78.8175',
	//         'flx:NVDA': '180.64',
	//         'flx:TSLA': '436.075'
	//         }
	//     }
	// }
	//
	// handle hip3 mids
	var data map[string]any = ccxt.SafeMapTyped(message, "data")
	var mids map[string]any = this.SafeDictMap(data, "mids", map[string]any{})
	if mids != nil {
		var keys []string = nil
		if mids != nil {
			keys = make([]string, 0, len(mids))
			for objectKey := range mids {
				keys = append(keys, objectKey)
			}
		}
		for i := 0; i < len(keys); i++ {
			var name string = keys[i]
			var marketId any = this.CoinToMarketId(name)
			var market map[string]any = this.SafeMarket(marketId, nil, nil, "swap")
			var symbol *string = ccxt.SafeStringPtr(market["symbol"])
			var ticker map[string]any = ccxt.MapTyped(this.ParseWsTicker(map[string]any{
				"price": this.SafeNumber(mids, name),
			}, market))
			this.Tickers.Store(symbol, ticker)
		}
		var messageHash string = "tickers"
		var dexMessage *string = this.SafeString(data, "dex")
		if dexMessage != nil {
			messageHash += ":" + *dexMessage
		}
		client.(ccxt.ClientInterface).Resolve(this.Tickers.ToMap(), messageHash)
	}
	return true
}
func (this *Hyperliquid) HandleActiveAssetCtx(client any, message map[string]any) bool {
	//
	//     {
	//         "channel": "activeAssetCtx",
	//         "data": {
	//             "coin": "BTC",
	//             "ctx": {
	//                 "dayNtlVlm": "1169046.29406",
	//                 "prevDayPx": "15.322",
	//                 "markPx": "14.3161",
	//                 "midPx": "14.314",
	//                 "oraclePx": "14.32",
	//                 "funding": "0.0000125",
	//                 "openInterest": "688.11",
	//                 "premium": "0.00031774",
	//                 "impactPxs": [ "14.3047", "14.3444" ]
	//             }
	//         }
	//     }
	//
	// the spot variant arrives on the activeSpotAssetCtx channel and carries
	// "circulatingSupply" instead of the swap-only fields
	//
	var data map[string]any = ccxt.SafeMapTyped(message, "data")
	var coin *string = this.SafeString(data, "coin")
	var marketId any = this.CoinToMarketId(coin)
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var ctx map[string]any = this.SafeDictMap(data, "ctx", map[string]any{})
	var ticker map[string]any = ccxt.MapTyped(this.ParseWsTicker(ctx, market))
	this.Tickers.Store(symbol, ticker)
	var messageHash string = "ticker:" + *symbol
	client.(ccxt.ClientInterface).Resolve(ticker, messageHash)
	return true
}
func (this *Hyperliquid) ParseWsTicker(rawTicker map[string]any, optionalArgs ...any) any {
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	return ccxt.TickerToMap(this.ParseTicker(rawTicker, market))
}
func (this *Hyperliquid) HandleMyTrades(client any, message map[string]any) {
	//
	//     {
	//         "channel": "userFills",
	//         "data": {
	//             "isSnapshot": true,
	//             "user": "0x15f43d1f2dee81424afd891943262aa90f22cc2a",
	//             "fills": [
	//                 {
	//                     "coin": "BTC",
	//                     "px": "72528.0",
	//                     "sz": "0.11693",
	//                     "side": "A",
	//                     "time": 1710208712815,
	//                     "startPosition": "0.11693",
	//                     "dir": "Close Long",
	//                     "closedPnl": "-0.81851",
	//                     "hash": "0xc5adaf35f8402750c218040b0a7bc301130051521273b6f398b3caad3e1f3f5f",
	//                     "oid": 7484888874,
	//                     "crossed": true,
	//                     "fee": "2.968244",
	//                     "liquidationMarkPx": null,
	//                     "tid": 567547935839686,
	//                     "cloid": null
	//                 }
	//             ]
	//         }
	//     }
	//
	// an empty snapshot still seeds the liquidations cache
	this.HandleMyLiquidations(client, message)
	var entry map[string]any = ccxt.SafeMapTyped(message, "data")
	if this.MyTrades == nil {
		var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		this.MyTrades = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var trades any = this.MyTrades
	var symbols map[string]any = map[string]any{}
	var data []any = ccxt.SafeListTyped(entry, "fills")
	var dataLength int = len(data)
	if dataLength == 0 {
		return
	}
	for i := 0; i < len(data); i++ {
		var rawTrade any = func() any {
			if i >= 0 && i < len(data) {
				return ccxt.DerefScalar(data[i])
			}
			return nil
		}()
		var parsed map[string]any = ccxt.MapTyped(this.ParseWsTrade(rawTrade))
		var symbol *string = ccxt.SafeStringPtr(parsed["symbol"])
		if symbol != nil {
			symbols[*symbol] = true
		}
		trades.(ccxt.Appender).Append(parsed)
	}
	var keys []string = nil
	if symbols != nil {
		keys = make([]string, 0, len(symbols))
		for objectKey := range symbols {
			keys = append(keys, objectKey)
		}
	}
	for i := 0; i < len(keys); i++ {
		var currentMessageHash *string = ccxt.SafeStringPtr(ccxt.Add("myTrades:", keys[i]))
		client.(ccxt.ClientInterface).Resolve(trades, currentMessageHash)
	}
	// non-symbol specific
	var messageHash string = "myTrades"
	client.(ccxt.ClientInterface).Resolve(trades, messageHash)
}
func (this *Hyperliquid) HandleMyLiquidations(client any, message map[string]any) {
	//
	// userFills message, see handleMyTrades, liquidation fills carry
	//
	//     "liquidation": {
	//         "liquidatedUser": "0x5c902b2eb0e1d9eb9a232014824ae6247df0a480",
	//         "markPx": "4.69112",
	//         "method": "market"
	//     }
	//
	var entry map[string]any = ccxt.SafeMapTyped(message, "data")
	// every subscription starts with a snapshot, a resubscribe replays it
	var isSnapshot *bool = this.SafeBool(entry, "isSnapshot", false)
	if (isSnapshot != nil && *isSnapshot) || (ccxt.IsEqual(this.MyLiquidations, nil)) {
		var limit *int64 = this.SafeInteger(this.Options, "myLiquidationsLimit", 1000)
		this.MyLiquidations = ccxt.NewArrayCache(limit)
	}
	var user *string = this.SafeStringLower(entry, "user")
	var fills []any = ccxt.SafeListTyped(entry, "fills")
	var newLiquidations []any = []any{}
	for i := 0; i < len(fills); i++ {
		var fill any = func() any {
			if i >= 0 && i < len(fills) {
				return ccxt.DerefScalar(fills[i])
			}
			return nil
		}()
		var liquidation map[string]any = ccxt.SafeMapTyped(fill, "liquidation")
		// liquidator fills carry the liquidated counterparty here
		if this.SafeStringLower(liquidation, "liquidatedUser") == user || (this.SafeStringLower(liquidation, "liquidatedUser") != nil && user != nil && *this.SafeStringLower(liquidation, "liquidatedUser") == *user) {
			newLiquidations = append(newLiquidations, this.ParseLiquidation(fill))
		}
	}
	var newLiquidationsLength int = len(newLiquidations)
	if newLiquidationsLength == 0 {
		return
	}
	var cache any = this.MyLiquidations
	var symbols map[string]any = map[string]any{}
	for i := 0; i < newLiquidationsLength; i++ {
		var liquidation any = func() any {
			if i >= 0 && i < len(newLiquidations) {
				return ccxt.DerefScalar(newLiquidations[i])
			}
			return nil
		}()
		cache.(ccxt.Appender).Append(liquidation)
		ccxt.AddElementToObject(symbols, ccxt.GetValue(liquidation, "symbol"), true)
	}
	var keys []string = nil
	if symbols != nil {
		keys = make([]string, 0, len(symbols))
		for objectKey := range symbols {
			keys = append(keys, objectKey)
		}
	}
	for i := 0; i < len(keys); i++ {
		var symbol string = keys[i]
		var symbolLiquidations any = this.FilterBySymbol(newLiquidations, symbol)
		client.(ccxt.ClientInterface).Resolve(symbolLiquidations, "myLiquidations::"+symbol)
	}
	client.(ccxt.ClientInterface).Resolve(newLiquidations, "myLiquidations")
}

/**
 * @method
 * @name hyperliquid#watchTrades
 * @description watches information on multiple trades made in a market
 * @see https://hyperliquid.gitbook.io/hyperliquid-docs/for-developers/api/websocket/subscriptions
 * @param {string} symbol unified market symbol of the market trades were made in
 * @param {int} [since] the earliest time in ms to fetch trades for
 * @param {int} [limit] the maximum number of trade structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
 */
func (this *Hyperliquid) WatchTradesAsync(symbol any, optionalArgs ...any) <-chan ccxt.AsyncResult[[]any] {
	ch := make(chan ccxt.AsyncResult[[]any], 1)
	go this.watchTradesBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Hyperliquid) watchTradesBody(ch chan ccxt.AsyncResult[[]any], symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var symbolValue *string = ccxt.SafeStringPtr(market["symbol"])
	var messageHash string = "trade:" + *symbolValue
	var url *string = ccxt.SafeStringPtr(ccxt.GetValue(ccxt.GetValue(this.Urls["api"], "ws"), "public"))
	var request map[string]any = map[string]any{
		"method": "subscribe",
		"subscription": map[string]any{
			"type": "trades",
			"coin": func() any {
				if market["swap"] == true {
					return market["baseName"]
				}
				return market["id"]
			}(),
		},
	}
	var message map[string]any = this.Extend(request, params)

	r1 := <-this.WaitForPendingUnsubscribeAsync(url, messageHash)
	if r1.Err != nil {
		panic(r1.Err)
	}

	r2 := <-this.Watch(url, messageHash, message, messageHash)
	if r2.Err != nil {
		panic(r2.Err)
	}
	var trades ccxt.ArrayCacheInterface = ccxt.AsArrayCache(r2.Value)
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(trades).GetLimit(symbolValue, limit)
	}

	ch <- ccxt.AsyncResult[[]any]{Value: this.FilterBySinceLimit(trades, since, limitResolved, "timestamp", true)}
	return nil
}

