func (this *Hyperliquid) HandleOHLCV(client any, message map[string]any) {
	//
	//     {
	//         channel: 'candle',
	//         data: {
	//             t: 1710146280000,
	//             T: 1710146339999,
	//             s: 'BTC',
	//             i: '1m',
	//             o: '71400.0',
	//             c: '71411.0',
	//             h: '71422.0',
	//             l: '71389.0',
	//             v: '1.20407',
	//             n: 20
	//         }
	//     }
	//
	var data map[string]any = this.SafeDictMap(message, "data", map[string]any{})
	var base *string = this.SafeString(data, "s")
	var marketId any = this.CoinToMarketId(base)
	var symbol *string = this.SafeSymbol(marketId)
	var timeframe *string = this.SafeString(data, "i")
	if !(ccxt.InOp(this.Ohlcvs, symbol)) {
		ccxt.AddElementToObject(this.Ohlcvs, symbol, map[string]any{})
	}
	if !(ccxt.InOp(ccxt.GetValue(this.Ohlcvs, symbol), timeframe)) {
		var limit *int64 = this.SafeInteger(this.Options, "OHLCVLimit", 1000)
		stored := ccxt.NewArrayCacheByTimestamp(limit)
		ccxt.AddElementToObject(ccxt.GetValue(this.Ohlcvs, symbol), timeframe, stored)
	}
	var ohlcv any = ccxt.GetValue(ccxt.GetValue(this.Ohlcvs, symbol), timeframe)
	var parsed any = ccxt.OHLCVToList(this.ParseOHLCV(data))
	ohlcv.(ccxt.Appender).Append(parsed)
	var messageHash *string = ccxt.SafeStringPtr(ccxt.Add(ccxt.Add(ccxt.Add("candles:", timeframe), ":"), symbol))
	client.(ccxt.ClientInterface).Resolve(ohlcv, messageHash)
}
func (this *Hyperliquid) HandleWsPost(client any, message map[string]any) {
	//    {
	//         channel: "post",
	//         data: {
	//             id: <number>,
	//             response: {
	//                  type: "info" | "action" | "error",
	//                  payload: { ... }
	//         }
	//    }
	var data map[string]any = ccxt.SafeMapTyped(message, "data")
	var id *string = this.SafeString(data, "id")
	var response map[string]any = ccxt.SafeMapTyped(data, "response")
	var payload map[string]any = ccxt.SafeMapTyped(response, "payload")
	client.(ccxt.ClientInterface).Resolve(payload, id)
}

/**
 * @method
 * @name hyperliquid#watchBalance
 * @description watch balance and get the amount of funds available for trading or funds locked in orders
 * @see https://hyperliquid.gitbook.io/hyperliquid-docs/for-developers/api/websocket/subscriptions
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.dex] for hip3 tokens subscription, eg: 'xyz' or 'flx'
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Hyperliquid) WatchBalanceAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[map[string]any] {
	ch := make(chan ccxt.AsyncResult[map[string]any], 1)
	go this.watchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Hyperliquid) watchBalanceBody(ch chan ccxt.AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var userAddress any = nil
	var userAddressResult any = this.HandlePublicAddress("watchBalance", params)
	if derefPtr := this.SafeString(userAddressResult, 0); derefPtr != nil {
		userAddress = *derefPtr
	} else {
		userAddress = nil
	}
	var paramsValue any = this.SafeDict(userAddressResult, 1, params)
	typeVar, paramsMarketType := this.HandleMarketTypeAndParams("watchBalance", nil, paramsValue)
	var isUnifiedEnabled any = nil

	r1 := <-this.IsUnifiedEnabledAsync("watchBalance", userAddress, false, paramsMarketType)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var unifiedResult []any = r1.Value
	isUnifiedEnabled = this.SafeBool(unifiedResult, 0)
	var paramsValue2 any = this.SafeDict(unifiedResult, 1, paramsMarketType)
	var dex *string = this.SafeString(paramsValue2, "dex")
	var isSpot bool = ((typeVar != nil && *typeVar == "spot") || (ccxt.IsEqual(isUnifiedEnabled, true))) && (dex == nil)
	var topic string = "clearinghouseState"
	if isSpot == true {
		topic = "spotState"
	}
	var messageHash string = topic + "::balance"
	var url *string = ccxt.SafeStringPtr(ccxt.GetValue(ccxt.GetValue(this.Urls["api"], "ws"), "public"))
	var subscription map[string]any = map[string]any{
		"type": topic,
		"user": userAddress,
	}
	if isSpot == true {
		if ccxt.IsEqual(isUnifiedEnabled, true) {
			subscription["isPortfolioMargin"] = true
		}
	} else {
		if dex != nil {
			subscription["dex"] = dex
		}
	}
	var request map[string]any = map[string]any{
		"method":       "subscribe",
		"subscription": subscription,
	}
	var message map[string]any = this.Extend(request, paramsValue2)
	// the swap topic 'clearinghouseState' is one server subscription shared
	// with watchPositions, so a pending unWatchPositions delays this watch
	// too - its ack tears the shared stream down and sweeps both futures

	r2 := <-this.WaitForPendingUnsubscribeAsync(url, topic)
	if r2.Err != nil {
		panic(r2.Err)
	}

	r3 := <-this.Watch(url, messageHash, message, topic)
	if r3.Err != nil {
		panic(r3.Err)
	}
	var resolved map[string]any
	switch resolvedBox := r3.Value.(type) {
	case map[string]any:
		resolved = resolvedBox
	case *sync.Map:
		resolved = ccxt.SafeMapToMap(resolvedBox)
	case nil:
	default:
		panic(ccxt.ExchangeError("resolved value is not map[string]any"))
	}
	ch <- ccxt.AsyncResult[map[string]any]{Value: resolved}
	return nil
}

/**
 * @method
 * @name hyperliquid#unWatchBalance
 * @description unWatches balance
 * @see https://hyperliquid.gitbook.io/hyperliquid-docs/for-developers/api/websocket/subscriptions
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} status of the unwatch request
 */
func (this *Hyperliquid) UnWatchBalanceAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[any] {
	ch := make(chan ccxt.AsyncResult[any], 1)
	go this.unWatchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Hyperliquid) unWatchBalanceBody(ch chan ccxt.AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var url *string = ccxt.SafeStringPtr(ccxt.GetValue(ccxt.GetValue(this.Urls["api"], "ws"), "public"))
	var userAddress any = nil
	var userAddressResult any = this.HandlePublicAddress("unWatchBalance", params)
	if derefPtr := this.SafeString(userAddressResult, 0); derefPtr != nil {
		userAddress = *derefPtr
	} else {
		userAddress = nil
	}
	var paramsValue any = this.SafeDict(userAddressResult, 1, params)
	typeVar, paramsMarketType := this.HandleMarketTypeAndParams("unWatchBalance", nil, paramsValue)
	var isUnifiedEnabled any = nil

	r1 := <-this.IsUnifiedEnabledAsync("unWatchBalance", userAddress, false, paramsMarketType)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var unifiedResult []any = r1.Value
	isUnifiedEnabled = this.SafeBool(unifiedResult, 0)
	var paramsValue2 any = this.SafeDict(unifiedResult, 1, paramsMarketType)
	var dex *string = this.SafeString(paramsValue2, "dex")
	var isSpot bool = ((typeVar != nil && *typeVar == "spot") || (ccxt.IsEqual(isUnifiedEnabled, true))) && (dex == nil)
	var topic string = "clearinghouseState"
	if isSpot == true {
		topic = "spotState"
	}
	var messageHash string = "unsubscribe" + ":" + topic
	var request map[string]any = map[string]any{
		"method": "unsubscribe",
		"subscription": map[string]any{
			"type": topic,
			"user": userAddress,
		},
	}
	var message map[string]any = this.Extend(request, paramsValue2)

	r2 := <-this.Watch(url, messageHash, message, messageHash)
	if r2.Err != nil {
		panic(r2.Err)
	}
	ch <- ccxt.AsyncResult[any]{Value: r2.Value}
	return nil
}
func (this *Hyperliquid) HandleBalance(client any, message map[string]any) {
	//
	// spot
	// {
	//     "channel": "spotState",
	//     "data": {
	//         "user": "0xeeeeexxxxeeeee",
	//         "spotState": {
	//             "balances": [
	//                 {
	//                     "coin": "USDH",
	//                     "token": 360,
	//                     "total": "0.0",
	//                     "hold": "0.0",
	//                     "entryNtl": "0.0"
	//                 }
	//             ],
	//             "tokenToAvailableAfterMaintenance": [
	//                 [
	//                     0,
	//                     "56.1"
	//                 ]
	//             ]
	//         }
	//     }
	// }
	// swap
	// {
	//     "channel": "clearinghouseState",
	//     "data": {
	//         "dex": "",
	//         "user": "0xeeeeexxxxeeeee",
	//         "clearinghouseState": {
	//             "marginSummary": {
	//                 "accountValue": "0.0",
	//                 "totalNtlPos": "0.0",
	//                 "totalRawUsd": "0.0",
	//                 "totalMarginUsed": "0.0"
	//             },
	//             "crossMarginSummary": {
	//                 "accountValue": "0.0",
	//                 "totalNtlPos": "0.0",
	//                 "totalRawUsd": "0.0",
	//                 "totalMarginUsed": "0.0"
	//             },
	//             "crossMaintenanceMarginUsed": "0.0",
	//             "withdrawable": "0.0",
	//             "assetPositions": [],
	//             "time": 1776000003409
	//         }
	//     }
	// }
	//
	if ccxt.IsEqual(this.Balance, nil) {
		this.Balance = map[string]any{}
	}
	var topic *string = this.SafeString(message, "channel")
	var info any = nil
	var rawBalances []any = []any{}
	var account any = nil
	var timestamp *int64 = nil
	var data map[string]any = ccxt.SafeMapTyped(message, "data")
	if topic != nil && *topic == "spotState" {
		var spotState map[string]any = ccxt.SafeMapTyped(data, "spotState")
		rawBalances = ccxt.ArrayTyped(this.SafeList(spotState, "balances", []any{}))
		account = "spot"
		info = rawBalances
	}
	if topic != nil && *topic == "clearinghouseState" {
		account = "swap"
		var clearinghouseState any = this.SafeDict(data, "clearinghouseState")
		rawBalances = append(rawBalances, clearinghouseState)
		info = clearinghouseState
		timestamp = this.SafeInteger(clearinghouseState, "time")
		this.HandlePositions(client, message)
	}
	for i := 0; i < len(rawBalances); i++ {
		this.ParseWsBalance(func() any {
			if i >= 0 && i < len(rawBalances) {
				return ccxt.DerefScalar(rawBalances[i])
			}
			return nil
		}(), account)
	}
	if ccxt.IsEqual(this.SafeValue(this.Balance, account), nil) {
		ccxt.AddElementToObject(this.Balance, account, map[string]any{})
	}
	ccxt.AddElementToObject(ccxt.GetValue(this.Balance, account), "info", info)
	ccxt.AddElementToObject(ccxt.GetValue(this.Balance, account), "timestamp", timestamp)
	ccxt.AddElementToObject(ccxt.GetValue(this.Balance, account), "datetime", this.Iso8601(timestamp))
	ccxt.AddElementToObject(this.Balance, account, this.SafeBalance(ccxt.GetValue(this.Balance, account)))
	if topic != nil {
		var messageHash string = *topic + "::balance"
		client.(ccxt.ClientInterface).Resolve(ccxt.GetValue(this.Balance, account), messageHash)
	}
}
func (this *Hyperliquid) ParseWsBalance(balance any, optionalArgs ...any) {
	//
	// spot
	//     {
	//         "coin": "USDH",
	//         "token": 360,
	//         "total": "0.0",
	//         "hold": "0.0",
	//         "entryNtl": "0.0"
	//     }
	// swap
	//     {
	//         "marginSummary": {
	//             "accountValue": "0.0",
	//             "totalNtlPos": "0.0",
	//             "totalRawUsd": "0.0",
	//             "totalMarginUsed": "0.0"
	//         },
	//         "crossMarginSummary": {
	//             "accountValue": "0.0",
	//             "totalNtlPos": "0.0",
	//             "totalRawUsd": "0.0",
	//             "totalMarginUsed": "0.0"
	//         },
	//         "crossMaintenanceMarginUsed": "0.0",
	//         "withdrawable": "0.0",
	//         "assetPositions": [],
	//         "time": 1776000003409
	//     }
	//
	accountType := ccxt.GetArg(optionalArgs, 0, nil)
	_ = accountType
	var account map[string]any = this.Account()
	var currencyId *string = this.SafeString(balance, "coin")
	var code *string = nil
	if currencyId == nil {
		code = ccxt.SafeStringPtr("USDC")
		var marginSummary map[string]any = ccxt.SafeMapTyped(balance, "marginSummary")
		account["free"] = this.SafeString(balance, "withdrawable")
		account["used"] = this.SafeString(marginSummary, "totalMarginUsed")
		account["total"] = this.SafeString(marginSummary, "accountValue")
	} else {
		code = this.SafeCurrencyCode(currencyId)
		account["used"] = this.SafeString(balance, "hold")
		account["total"] = this.SafeString(balance, "total")
	}
	if accountType != nil {
		if ccxt.IsEqual(this.SafeValue(this.Balance, accountType), nil) {
			ccxt.AddElementToObject(this.Balance, accountType, map[string]any{})
		}
		if (accountType != nil) && (code != nil) {
			ccxt.AddElementToObject(ccxt.GetValue(this.Balance, accountType), code, account)
		}
	} else {
		if code != nil {
			ccxt.AddElementToObject(this.Balance, code, account)
		}
	}
}

/**
 * @method
 * @name hyperliquid#watchPositions
 * @see https://hyperliquid.gitbook.io/hyperliquid-docs/for-developers/api/websocket/subscriptions
 * @description watch all open positions
 * @param {string[]} [symbols] list of unified market symbols
 * @param {int} [since] the earliest time in ms to fetch positions for
 * @param {int} [limit] the maximum number of positions to retrieve
 * @param {object} params extra parameters specific to the exchange API endpoint
 * @param {string} [params.dex] for hip3 tokens subscription, eg: 'xyz' or 'flx`, if symbols are provided we will infer it from the first symbol's market
 * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/en/latest/manual.html#position-structure}
 */
func (this *Hyperliquid) WatchPositionsAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[[]any] {
	ch := make(chan ccxt.AsyncResult[[]any], 1)
	go this.watchPositionsBody(ch, optionalArgs...)
	return ch
}
func (this *Hyperliquid) watchPositionsBody(ch chan ccxt.AsyncResult[[]any], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbols := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbols
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var userAddress *string = nil
	var userAddressResult any = this.HandlePublicAddress("watchPositions", params)
	userAddress = this.SafeString(userAddressResult, 0)
	var paramsValue any = this.SafeDict(userAddressResult, 1, params)
	var topic string = "clearinghouseState"
	var messageHash string = topic + "::positions"
	var hasSymbols bool = (symbols != nil) && !this.IsEmpty(symbols)
	var symbolsNormalized any = symbols
	if hasSymbols {
		symbolsNormalized = this.MarketSymbols(symbols)
	}
	if hasSymbols && (!ccxt.IsEqual(symbolsNormalized, nil)) {
		messageHash += "::" + ccxt.Join(symbolsNormalized, ",")
	}
	var url *string = ccxt.SafeStringPtr(ccxt.GetValue(ccxt.GetValue(this.Urls["api"], "ws"), "public"))
	var subscription map[string]any = map[string]any{
		"type": topic,
		"user": userAddress,
	}
	var dexName any = this.GetDexFromSymbols("watchPositions", symbolsNormalized)
	if dexName != nil {
		subscription["dex"] = dexName
	}
	var request map[string]any = map[string]any{
		"method":       "subscribe",
		"subscription": subscription,
	}
	var message map[string]any = this.Extend(request, paramsValue)
	// the topic 'clearinghouseState' is one server subscription shared with
	// the swap watchBalance, so a pending unWatchBalance delays this watch
	// too - its ack tears the shared stream down and sweeps both futures

	r1 := <-this.WaitForPendingUnsubscribeAsync(url, topic)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var client ccxt.ClientInterface = this.Client(url)
	this.SetPositionsCache(client, symbolsNormalized)
	var cache any = this.Positions

	r2 := <-this.Watch(url, messageHash, message, topic)
	if r2.Err != nil {
		panic(r2.Err)
	}
	newPositions := r2.Value
	if this.NewUpdates {

		var resolved []any
		switch resolvedBox := newPositions.(type) {
		case []any:
			resolved = resolvedBox
		case ccxt.IArrayCache:
			resolved = resolvedBox.ToArray()
		case nil:
		default:
			panic(ccxt.ExchangeError("resolved value is not []any"))
		}
		ch <- ccxt.AsyncResult[[]any]{Value: resolved}
		return nil
	}

	ch <- ccxt.AsyncResult[[]any]{Value: this.FilterBySymbolsSinceLimit(cache, symbolsNormalized, since, limit, true)}
	return nil
}
func (this *Hyperliquid) SetPositionsCache(client any, optionalArgs ...any) {
	var symbols []string = ccxt.GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	if this.Positions != nil {
		return
	}
	this.Positions = ccxt.NewArrayCacheBySymbolBySide()
}
func (this *Hyperliquid) HandlePositions(client any, message map[string]any) {
	if this.Positions == nil {
		this.Positions = ccxt.NewArrayCacheBySymbolBySide()
	}
	var cache any = this.Positions
	var data map[string]any = ccxt.SafeMapTyped(message, "data")
	var clearinghouseState map[string]any = ccxt.SafeMapTyped(data, "clearinghouseState")
	var newPositions []any = []any{}
	var rawPositions []any = ccxt.SafeListTyped(clearinghouseState, "assetPositions")
	for i := 0; i < len(rawPositions); i++ {
		var rawPosition any = func() any {
			if i >= 0 && i < len(rawPositions) {
				return ccxt.DerefScalar(rawPositions[i])
			}
			return nil
		}()
		var position map[string]any = ccxt.MapTyped(this.ParsePosition(rawPosition))
		newPositions = append(newPositions, position)
		cache.(ccxt.Appender).Append(position)
	}
	var baseMessageHash string = "clearinghouseState::positions"
	var messageHashes []any = ccxt.ArrayTyped(this.FindMessageHashes(ccxt.AsClient(client), baseMessageHash))
	for i := 0; i < len(messageHashes); i++ {
		var messageHash *string = ccxt.SafeStringPtr(func() any {
			if i >= 0 && i < len(messageHashes) {
				return ccxt.DerefScalar(messageHashes[i])
			}
			return nil
		}())
		var parts []string = strings.Split(*messageHash, "::")
		var symbolsString *string = this.SafeString(parts, 2)
		if symbolsString == nil {
			continue
		}
		var symbols []string = strings.Split(*symbolsString, ",")
		var positions any = this.FilterByArray(newPositions, "symbol", symbols, false)
		if !this.IsEmpty(positions) {
			client.(ccxt.ClientInterface).Resolve(positions, messageHash)
		}
	}
	client.(ccxt.ClientInterface).Resolve(newPositions, baseMessageHash)
}

